    private $db;private $send;private bool $real;private string $base;
    public function __construct($db=null,?callable $send=null,?string $base=null){$this->db=$db??db_connect();$this->real=$send===null;$this->base=$base??base_url();$this->send=$send??static fn($phone,$text,$url,$filename)=>(new WhatsAppGateway())->request($phone,$text,'document',$url,$filename);}
    public function send(int $class,string $format,string $number,int $owner,string $recipient=''): array
    {
        $format=strtolower($format);if(!in_array($format,['excel','pdf'],true))throw new \InvalidArgumentException('Pilih format Excel atau PDF.');
        $phone=WhatsAppGateway::phone($number);if(!$phone)throw new \InvalidArgumentException('Nomor WhatsApp tujuan tidak valid.');$recipient=trim($recipient);if(mb_strlen($recipient)>180)throw new \InvalidArgumentException('Nama penerima terlalu panjang.');
        $db=$this->db;$klass=$db->table('kelas')->select('id,nama_kelas')->where(['id'=>$class,'wali_kelas_id'=>$owner])->get()->getRowArray();if(!$klass)throw new \InvalidArgumentException('Kelas tidak dapat diakses.');
        $host=strtolower((string)parse_url($this->base,PHP_URL_HOST));if(!in_array(parse_url($this->base,PHP_URL_SCHEME),['http','https'],true)||!$host||in_array($host,['localhost','::1','[::1]','0.0.0.0'],true)||str_starts_with($host,'127.'))throw new \InvalidArgumentException('Gateway memerlukan alamat aplikasi publik untuk mengambil berkas. Pengiriman tersedia pada VPS.');
        if($this->real&&!(new WhatsAppGateway())->configured())throw new \InvalidArgumentException('Gateway WhatsApp belum siap. Periksa menu WhatsApp Gateway.');
        $rows=LatenessReportExport::rows($class);$now=new \DateTimeImmutable('now',new \DateTimeZone('Asia/Jakarta'));$stamp=$now->format('d-m-Y H:i:s');$extension=$format==='excel'?'xls':'pdf';$token=bin2hex(random_bytes(32));$file=bin2hex(random_bytes(32)).'.'.$extension;$path=WRITEPATH.'status-kedisiplinan/'.$file;
        $bytes=$format==='excel'?LatenessReportExport::excel($rows,$klass['nama_kelas'],$stamp):LatenessReportExport::pdf($rows,$klass['nama_kelas'],$stamp);$filename='Status-Keterlambatan-'.preg_replace('/[^A-Za-z0-9_-]/','-',$klass['nama_kelas']).'.'.$extension;$title=$format==='excel'?'Excel':'PDF';$text='Berikut hasil Status Kedisiplinan Keterlambatan kelas '.$klass['nama_kelas'].' dalam format '.$title.'. Tabel memuat nama, NIS, jumlah keterlambatan, tanggal, alasan, dan status kedisiplinan. Dibuat '.$stamp.' WIB.';$snapshot=hash('sha256',json_encode([$klass,$rows,$format],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$key=hash('sha256',implode('|',[$owner,$class,$phone,$snapshot,bin2hex(random_bytes(16))]));$db->transBegin();
