                $messageRow=!empty($existing['message_id'])?$db->table('pesan_komunikasi')->where(['id'=>$existing['message_id'],'kelas_id'=>$class,'dibuat_oleh'=>$owner])->get()->getRowArray():null;
                if(!$messageRow){$db->table('pesan_komunikasi')->insert(['kelas_id'=>$class,'pengirim'=>'AIWalas','penerima'=>$recipient?:$phone,'nomor_tujuan'=>$phone,'isi_pesan'=>$text,'kategori'=>'Export Status Kedisiplinan '.$title,'status_pengiriman'=>'Disiapkan','dibuat_oleh'=>$owner]);$restored=$db->insertID();$db->table('status_kedisiplinan_pengiriman')->where('id',$existing['id'])->update(['message_id'=>$restored,'status'=>'pending','result_note'=>'Riwayat Komunikasi dipulihkan; status penerimaan penerima belum terkonfirmasi.']);$db->transCommit();return ['ok'=>true,'status'=>'pending','already'=>true,'message'=>'Permintaan sebelumnya tidak dikirim ulang. Catatan Komunikasi dipulihkan dengan status Pending; periksa gateway sebelum mencoba lagi.'];}
