                $db->transCommit();return ['ok'=>true,'status'=>'pending','already'=>true,'message'=>'Permintaan ini sudah tercatat Pending dan tidak dikirim ulang. Periksa nomor tujuan atau status gateway.'];}
            if(!is_dir(dirname($path))&&!mkdir(dirname($path),0770,true)&&!is_dir(dirname($path)))throw new \RuntimeException('Folder ekspor belum tersedia.');if(file_put_contents($path,$bytes,LOCK_EX)!==strlen($bytes))throw new \RuntimeException('Berkas ekspor gagal disimpan.');
            $db->table('pesan_komunikasi')->insert(['kelas_id'=>$class,'pengirim'=>'AIWalas','penerima'=>$recipient?:$phone,'nomor_tujuan'=>$phone,'isi_pesan'=>$text,'kategori'=>'Export Status Kedisiplinan '.$title,'status_pengiriman'=>'Disiapkan','dibuat_oleh'=>$owner]);$message=$db->insertID();$db->table('status_kedisiplinan_pengiriman')->insert(['session_key'=>$key,'kelas_id'=>$class,'owner_id'=>$owner,'format'=>$format,'nomor_tujuan'=>$phone,'berkas'=>$file,'token_hash'=>hash('sha256',$token),'berlaku_sampai'=>$now->modify('+24 hours')->format('Y-m-d H:i:s'),'message_id'=>$message,'status'=>'processing','dibuat_pada'=>$now->format('Y-m-d H:i:s')]);$dispatch=$db->insertID();if(!$db->transStatus())throw new \RuntimeException('Pengiriman belum dapat dicatat.');$db->transCommit();
        }catch(\Throwable $error){$db->transRollback();if(is_file($path))unlink($path);throw $error;}
        $status='unknown';$note='Gateway belum melaporkan hasil pengiriman.';try{$response=($this->send)($phone,$text,rtrim($this->base,'/').'/media/status-kedisiplinan/'.$token,$filename);$body=$response['response']??[];$confirmation=is_array($body)?($body['status']??$body['success']??null):null;if(($response['ok']??false)&&in_array(($response['outcome']??''),['sent','accepted'],true)){$status='sent';$note='Laporan status keterlambatan berhasil dikirim melalui gateway.';}elseif(($response['ok']??false)&&in_array($confirmation,[true,1,200,'true','success','sent','accepted','queued'],true)){$status='sent';$note='Laporan status keterlambatan berhasil dikirim melalui gateway.';}elseif(!($response['ok']??false)&&($response['outcome']??'')==='failed'){$status='failed';$note=$response['message']??'Gateway menolak pengiriman berkas.';}}catch(\Throwable $error){}
        $db->transBegin();$db->table('status_kedisiplinan_pengiriman')->where('id',$dispatch)->update(['status'=>$status,'result_note'=>$note]);$db->table('pesan_komunikasi')->where('id',$message)->update(['status_pengiriman'=>$status==='sent'?'Terkirim':($status==='failed'?'Gagal':'Disiapkan'),'dikirim_pada'=>$status==='sent'?$now->format('Y-m-d H:i:s'):null]);if(!$db->transStatus()){$db->transRollback();throw new \RuntimeException('Hasil pengiriman belum tercatat. Periksa menu Komunikasi.');}$db->transCommit();return ['ok'=>in_array($status,['sent','pending'],true),'status'=>$status,'already'=>false,'message'=>$note];
    }
